# New York, 1962 (pages 26-28): every district, read whole. A fusion candidate is
# (name, 'Democrat, Liberal', the bracketed total, [(party, votes), ...]): the Clerk's total is used.
# In the 3d the lines sum to 59,636 against a total of 59,635; in the 8th to 105,686 against 104,895
# (the recapitulation, p. 29, carries the totals).
def _f(name, d, l, total):
    return (name, 'Democrat, Liberal', total, [('Democrat', d), ('Liberal', l)])


